//go:build js && wasm

// Browser demo/test entry: registers window.runGoWasmEcho(resolve,
// reject). The page first installs window.__grpcDcBridge (the JS
// grpc-dc bridge over a native RTCDataChannel); this Go/WASM client
// facade — generated by protoc-gen-grpc-dc-wasm-go — then runs the
// four Echo call shapes through it and resolves with a JSON summary.
package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"syscall/js"

	echowasm "wasmecho"
	echo "grpcdc/examples"
)

func main() {
	js.Global().Set("runGoWasmEcho", js.FuncOf(run))
	select {} // keep the wasm runtime alive for callbacks
}

func run(_ js.Value, args []js.Value) any {
	resolve, reject := args[0], args[1]
	go func() {
		result, err := doEcho()
		if err != nil {
			reject.Invoke(js.Global().Get("Error").New(err.Error()))
			return
		}
		raw, _ := json.Marshal(result)
		resolve.Invoke(string(raw))
	}()
	return nil
}

func doEcho() (map[string]any, error) {
	bridge := js.Global().Get("__grpcDcBridge")
	if bridge.Type() != js.TypeObject {
		return nil, fmt.Errorf("__grpcDcBridge is not installed")
	}
	client := echowasm.NewEchoClient(bridge)
	req := func(message string, count int32) *echo.EchoRequest {
		return &echo.EchoRequest{Message: message, Count: count}
	}
	out := map[string]any{}

	unary, err := client.Unary(req("hello", 0))
	if err != nil {
		return nil, err
	}
	out["unary"] = unary.Message

	var ticks []int32
	if err := client.ServerStream(req("tick", 3), func(resp *echo.EchoResponse) error {
		ticks = append(ticks, resp.Index)
		return nil
	}); err != nil {
		return nil, err
	}
	out["ticks"] = ticks

	joined, err := client.ClientStream(req("a", 0), req("b", 0))
	if err != nil {
		return nil, err
	}
	out["joined"] = joined.Message

	var echoed []string
	if err := client.Bidi([]*echo.EchoRequest{req("x", 0), req("y", 0)},
		func(resp *echo.EchoResponse) error {
			echoed = append(echoed, resp.Message)
			return nil
		}); err != nil {
		return nil, err
	}
	out["echoed"] = echoed

	// BDD deepening: failure, metadata, unknown-method, cancel,
	// and deadline scenarios executed by this module.
	codeOf := func(err error) int {
		var se *echowasm.StatusError
		if errors.As(err, &se) {
			return se.Code
		}
		if err != nil {
			return -1
		}
		return 0
	}

	_, failErr := client.Unary(req("fail", 0))
	out["unaryFailureCode"] = codeOf(failErr)

	metadataRaw, err := echowasm.CallUnaryWithOptions(bridge, "/echo.Echo/Unary",
		req("hello", 0).MarshalDC(), map[string]string{"x-echo": "meta"}, 0)
	if err != nil {
		return nil, err
	}
	var metadataResp echo.EchoResponse
	if err := metadataResp.UnmarshalDC(metadataRaw); err != nil {
		return nil, err
	}
	out["metadataMessage"] = metadataResp.Message

	out["serverStreamFailureCode"] = codeOf(client.ServerStream(req("fail", 3),
		func(resp *echo.EchoResponse) error { return nil }))
	out["bidiFailureCode"] = codeOf(client.Bidi([]*echo.EchoRequest{req("fail", 0)},
		func(resp *echo.EchoResponse) error { return nil }))

	_, rawErr := echowasm.CallUnaryWithOptions(bridge, "/echo.Echo/Nope",
		req("hello", 0).MarshalDC(), nil, 0)
	out["unknownMethodCode"] = codeOf(rawErr)

	cancelSeen := 0
	cancelErr := echowasm.CallServerStreamCancelAfter(bridge, "/echo.Echo/ServerStream",
		req("tick", 5).MarshalDC(), 1, func(payload []byte) error {
			cancelSeen++
			return nil
		})
	out["cancelTerminated"] = cancelErr == nil && cancelSeen == 1

	_, deadlineErr := echowasm.CallUnaryWithOptions(bridge, "/echo.Echo/Unary",
		(&echo.EchoRequest{Message: "slow", DelayMs: 600}).MarshalDC(), nil, 100)
	out["deadlineCode"] = codeOf(deadlineErr)

	return out, nil
}
